M2C_UNK osCreateMesgQueue(M2C_UNK *, M2C_UNK *, M2C_UNK); /* extern */
M2C_UNK osSendMesg(M2C_UNK *, M2C_UNK, M2C_UNK);    /* extern */
extern M2C_UNK workerLockQueue;
extern M2C_UNK workerLockMessages;

/* Creates the worker lock message queue (capacity 1) and posts one message so the lock starts released. */ void initWorkerLock(void) {
    osCreateMesgQueue(&workerLockQueue, &workerLockMessages, 1);
    osSendMesg(&workerLockQueue, 0, 0);
}
